import{_ as t,b as r,e as o,a7 as n}from"./chunks/framework.BCCJKnGb.js";const h=JSON.parse('{"title":"保研常见问题","description":"国新系推免常见问题：资格、排名、夏令营、预推免、材料、心态。","frontmatter":{"title":"保研常见问题","description":"国新系推免常见问题：资格、排名、夏令营、预推免、材料、心态。","type":"baoyan-faq","tags":["保研","FAQ","推免"],"updated":"2026-11-07T00:00:00.000Z"},"headers":[],"relativePath":"baoyan/faq.md","filePath":"baoyan/faq.md","lastUpdated":null}'),e={name:"baoyan/faq.md"};function s(p,a,l,i,d,b){return r(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="保研常见问题" tabindex="-1">保研常见问题 <a class="header-anchor" href="#保研常见问题" aria-label="Permalink to &quot;保研常见问题&quot;">​</a></h1><h2 id="资格与排名" tabindex="-1">资格与排名 <a class="header-anchor" href="#资格与排名" aria-label="Permalink to &quot;资格与排名&quot;">​</a></h2><p><strong>Q：排名差一点，还有机会吗？</strong><br> A：看当年细则是否有破格/专项通道；同时准备考研/留学/秋招的 plan B，不要把全部希望押在一条路上。</p><p><strong>Q：重修/补考会影响推免吗？</strong><br> A：看当年细则和学院认定；有疑问直接问教务老师，不要听“据说”。</p><p><strong>Q：综测/科研/素拓重要吗？</strong><br> A：看当年细则占比。学业成绩权重最高；科研和素拓是主要加分项。不要为了加分参加一堆不相关的活动，优先做能讲清楚收获的事。</p><p><strong>Q：六级要多少？</strong><br> A：2026 年分享会明确：本院报国新方向，<strong>六级 520</strong> 是硬门槛；不够就尽早重刷。外保看目标项目要求，可能更高。</p><h2 id="路径选择" tabindex="-1">路径选择 <a class="header-anchor" href="#路径选择" aria-label="Permalink to &quot;路径选择&quot;">​</a></h2><p><strong>Q：国新、专硕、学硕、外保怎么选？</strong><br> A：看你的兴趣和短板。国新重国际传播/英语/个人辨识度；专硕重专业书 + 专题 + 面试；学硕重学术潜质/研究经历；外保重成绩/科研/专业背景/目标项目匹配。不要一套材料投所有。</p><p><strong>Q：没有发表论文，外保是不是没戏？</strong><br> A：不是。分享会强调“研究过程与论文逻辑”比是否发表更重要；要能说清研究依据、方法、贡献。</p><h2 id="夏令营与预推免" tabindex="-1">夏令营与预推免 <a class="header-anchor" href="#夏令营与预推免" aria-label="Permalink to &quot;夏令营与预推免&quot;">​</a></h2><p><strong>Q：夏令营没入营，是不是没戏了？</strong><br> A：不是。预推免、本校推免、补录都可能有机会；及时关注通知，调整材料。</p><p><strong>Q：可以同时投多个学校吗？</strong><br> A：通常可以，但要注意时间冲突和最终确认规则；不要违约，影响学院声誉。</p><p><strong>Q：要不要海投？</strong><br> A：建议“梯度投递”：冲刺 2–3 个、匹配 3–4 个、保底 1–2 个；每个都认真准备，不要用同一份材料。</p><h2 id="材料" tabindex="-1">材料 <a class="header-anchor" href="#材料" aria-label="Permalink to &quot;材料&quot;">​</a></h2><p><strong>Q：个人陈述怎么写？</strong><br> A：结构建议：为什么选这个方向 → 我做了什么 → 我缺什么/为什么需要这个项目 → 未来计划。不要写成简历扩写。</p><p><strong>Q：推荐信找谁写？</strong><br> A：优先找教过你、了解你的老师；提前 2–3 周沟通，附上简历/成绩单/申请方向。</p><p><strong>Q：作品集要放什么？</strong><br> A：3–5 个完整作品，每个写清你的角色、过程、结果、反思；质量比数量重要。</p><h2 id="心态" tabindex="-1">心态 <a class="header-anchor" href="#心态" aria-label="Permalink to &quot;心态&quot;">​</a></h2><p><strong>Q：周围人都上岸了，我很焦虑怎么办？</strong><br> A：把注意力拉回“今天能做的 1 件事”；和信任的人聊；必要时联系学校心理中心。保研不是唯一的路，你的价值不由一个结果定义。</p><p><strong>Q：面试被问到不会的问题怎么办？</strong><br> A：承认不会，讲你的思考路径，或者把问题拉回你熟悉的领域；不要编造。</p><div class="tip custom-block"><p class="custom-block-title">还有问题？</p><p>在班级群/问卷里提交，我们每周整理一次；涉及个人情况的问题，建议直接问辅导员/教务老师。</p></div>',21)])])}const c=t(e,[["render",s]]);export{h as __pageData,c as default};
